export const code = async (inputs) => {
  const destination = inputs.destination;
  const budget = Number(inputs.budget);
  const baseCurrency = inputs.baseCurrency;
  const targetCurrency = inputs.targetCurrency;
  const durationDays = Number(inputs.durationDays);
  const email = inputs.email;

  if (!destination || !baseCurrency || !targetCurrency) {
    throw new Error("Missing destination or currency details");
  }

  if (budget <= 0 || durationDays <= 0) {
    throw new Error("Budget and duration must be greater than zero");
  }

  const response = await fetch(
    `https://api.frankfurter.dev/v2/rate/${baseCurrency.toLowerCase()}/${targetCurrency.toLowerCase()}`
  );

  if (!response.ok) {
    throw new Error("Could not fetch the exchange rate");
  }

  const data = await response.json();

  const convertedBudget = budget * data.rate;
  const dailyBudget = convertedBudget / durationDays;

  return {
    destination: destination,
    baseCurrency: data.base,
    targetCurrency: data.quote,
    exchangeRate: data.rate,
    rateDate: data.date,
    originalBudget: budget,
    convertedBudget: Number(convertedBudget.toFixed(2)),
    durationDays: durationDays,
    dailyBudget: Number(dailyBudget.toFixed(2)),
    email: email
  };
};
